"use client";
import { useState } from "react";

// Mesajın strukturunu müəyyən edək (TypeScript üçün əladır)
interface Message {
  role: "user" | "ai";
  text: string;
}

export default function ChatComponent() {
  const [messages, setMessages] = useState<Message[]>([
    { role: "ai", text: "Salam! Mən sənin Dashboard köməkçinim. Necə kömək edə bilərəm?" }
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);

  const sendMessage = async () => {
    if (!input.trim()) return;

    // 1. İstifadəçinin mesajını siyahıya əlavə et
    const userMsg: Message = { role: "user", text: input };
    setMessages((prev) => [...prev, userMsg]);
    setInput("");
    setLoading(true);

    try {
      // API-ya sorğu göndər
      const response = await fetch("/api/chat", {
        method: "POST",
        body: JSON.stringify({ prompt: input }),
      });
      const data = await response.json();

      // 2. AI-ın cavabını siyahıya əlavə et
      const aiMsg: Message = { role: "ai", text: data.text };
      setMessages((prev) => [...prev, aiMsg]);
    } catch (error) {
      console.error("Xəta:", error);
    } finally {
      setLoading(false);



    }
}

 return (
    <div className="flex flex-col gap-4">
      <div className="h-64 overflow-y-auto p-2 space-y-3">
        {messages.map((msg, index) => (
          <div key={index} className={`flex ${msg.role === "user" ? "justify-end" : "justify-start"}`}>
            <div className={`max-w-[80%] p-2 rounded-xl text-sm ${
              msg.role === "user" 
                ? "bg-blue-600 text-white rounded-tr-none" 
                : "bg-gray-800 text-gray-200 rounded-tl-none"
            }`}>
              {msg.text}
            </div>
          </div>
        ))}
        {loading && <div className="text-xs text-gray-500 animate-pulse">AI düşünür...</div>}
      </div>

      <div className="flex gap-2">
        <input 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && sendMessage()} // Enter-lə göndərmək
          className="..." 
        />
        <button onClick={sendMessage} disabled={loading}>Göndər</button>
      </div>
    </div>
  );
  };